content:
/* Website colours */
:root {
  --dark: #0d3b66;
  --mid: #b3cfe7;
  --light: #d6e6f2;
  --text: #08131f;
  --bs-body-color: var(--text); /* Bootstrap text colour */
}

/* Page */
body {background-color: var(--light);}

/* Tab bar */
.navbar.navbar-default, .navbar.navbar-inverse {background-color: var(--mid) !important; border-bottom: 1px solid var(--dark);}
.navbar .navbar-brand, .navbar .nav-link {color: var(--text) !important;}
.navbar .nav-link.active {font-weight: bold; border-bottom: 2px solid var(--dark);}

/* Intro box, as on the website */
.app-intro {
  background-color: var(--mid);
  border: 2px solid var(--dark);
  border-radius: 6px;
  padding: 0.9rem 1.2rem;
  margin: 1rem;
}
.app-intro p:last-child {margin-bottom: 0;}

/* Cards, sidebar and value boxes */
.card {background-color: #ffffff; border: 1px solid var(--dark); border-radius: 6px;}
.bslib-sidebar-layout {border: 1px solid var(--dark); border-radius: 6px;}
.bslib-sidebar-layout > .sidebar {background-color: var(--mid); overflow: visible;}
.card.bslib-value-box {background-color: var(--mid);}

/* Sidebar: controls move with the page */
.bslib-sidebar-layout > .sidebar > .sidebar-content {position: sticky; top: 0;}

/* Value boxes: centred, larger number, less padding */
.bslib-value-box .value-box-area {align-items: center; text-align: center; padding-top: 0.6rem !important; padding-bottom: 0.6rem !important;}
.bslib-value-box .value-box-value {font-size: 2.6rem;}
.bslib-value-box .value-box-title {font-weight: 600;}
.bslib-value-box .shiny-output-error-validation {font-size: 1.5rem;} /* messages smaller than numbers, on one line */

/* Error messages */
.shiny-output-error-validation {color: var(--text);}

/* Card headers and footers */
.card-header, .card-footer {background-color: var(--light);}
.card-header {font-weight: 600;}

/* Footer with an empty note */
.card-footer:has(.shiny-text-output:empty) {display: none;}

/* Slider: no small ticks between years */
.irs-grid-pol.small {display: none;}

/* Note above the value boxes, like the help text */
#area_missing_note {color: var(--dark);}

/* About tab: same text width as the website */
.tab-pane[data-value="About"] {max-width: 900px; margin: 0 auto;}

/* Help text (!important overrides Bootstrap) */
.help-block, .irs-grid-text {color: var(--dark) !important;}

/* Menu button on phones */
.navbar .navbar-toggle, .navbar .navbar-toggler {background-color: var(--dark);}

/* Charts: normal cursor, as they can only be hovered */
.js-plotly-plot .plotly .nsewdrag {cursor: default;}

/* Map frame, as for images on the website */
.leaflet-container {border: 1px solid var(--dark); border-radius: 6px;}

/* Map clusters in blues */
.marker-cluster-small {background-color: rgba(179, 207, 231, 0.6);}
.marker-cluster-small div {background-color: rgba(179, 207, 231, 0.9);}
.marker-cluster-medium {background-color: rgba(90, 140, 190, 0.6);}
.marker-cluster-medium div {background-color: rgba(90, 140, 190, 0.9); color: #ffffff;}
.marker-cluster-large {background-color: rgba(13, 59, 102, 0.6);}
.marker-cluster-large div {background-color: rgba(13, 59, 102, 0.9); color: #ffffff;}
